INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-space-moon', 'Name a planet in our solar system.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'There are eight planets. Pluto was reclassified as a dwarf planet in 2006, so it does not count here.', 'https://science.nasa.gov/solar-system/planets/', 'NASA Solar System Exploration', '2026-11-21', 'NASA public domain', 'space', 1, 0, '[{"canonical":"Mercury","prior":8,"aliases":[]},{"canonical":"Venus","prior":10,"aliases":[]},{"canonical":"Earth","prior":12,"aliases":[]},{"canonical":"Mars","prior":24,"aliases":[]},{"canonical":"Jupiter","prior":20,"aliases":[]},{"canonical":"Saturn","prior":14,"aliases":[]},{"canonical":"Uranus","prior":4,"aliases":[]},{"canonical":"Neptune","prior":6,"aliases":[]}]', NULL);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-space-giants', 'Name a country in Central America.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Seven sovereign states sit on the Central American isthmus, from Guatemala to Panama. Mexico is counted with North America in this sample. Pending verification.', 'https://en.wikipedia.org/wiki/Central_America', 'Wikipedia: Central America', '2026-11-21', 'CC BY-SA 4.0', 'geography', 2, 0, '[{"canonical":"Belize","prior":2,"aliases":[]},{"canonical":"Costa Rica","prior":8,"aliases":[]},{"canonical":"El Salvador","prior":3,"aliases":[]},{"canonical":"Guatemala","prior":3,"aliases":[]},{"canonical":"Honduras","prior":3,"aliases":[]},{"canonical":"Nicaragua","prior":3,"aliases":[]},{"canonical":"Panama","prior":8,"aliases":[]}]', 'countries');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-space-orbits', 'Name a moon of Jupiter or Saturn.', 'name_one', NULL, 'lower', NULL, '[]', '[]', 'Jupiter and Saturn have well over 150 known moons between them. The four big Galilean moons of Jupiter were spotted in 1610.', 'https://science.nasa.gov/solar-system/moons/', 'NASA Solar System Exploration', '2026-11-21', 'NASA public domain', 'space', 2, 0, '[{"canonical":"Titan","prior":22,"aliases":[]},{"canonical":"Europa","prior":20,"aliases":[]},{"canonical":"Io","prior":14,"aliases":[]},{"canonical":"Ganymede","prior":14,"aliases":[]},{"canonical":"Callisto","prior":8,"aliases":[]},{"canonical":"Enceladus","prior":8,"aliases":[]},{"canonical":"Mimas","prior":3,"aliases":[]},{"canonical":"Iapetus","prior":2,"aliases":[]},{"canonical":"Rhea","prior":2,"aliases":[]},{"canonical":"Dione","prior":2,"aliases":[]},{"canonical":"Tethys","prior":2,"aliases":[]},{"canonical":"Hyperion","prior":1,"aliases":[]},{"canonical":"Phoebe","prior":1,"aliases":[]},{"canonical":"Amalthea","prior":1,"aliases":[]},{"canonical":"Janus","prior":1,"aliases":[]},{"canonical":"Himalia","prior":0.5,"aliases":[]},{"canonical":"Pandora","prior":0.5,"aliases":[]},{"canonical":"Prometheus","prior":0.5,"aliases":[]},{"canonical":"Epimetheus","prior":0.5,"aliases":[]},{"canonical":"Thebe","prior":0.5,"aliases":[]},{"canonical":"Metis","prior":0.5,"aliases":[]},{"canonical":"Adrastea","prior":0.5,"aliases":[]}]', NULL);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-space-light', 'Name one of the 88 official constellations.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'The International Astronomical Union fixed 88 constellations in 1922. The Big Dipper is an asterism inside Ursa Major, not a constellation of its own.', 'https://www.iau.org/public/themes/constellations/', 'International Astronomical Union', '2026-11-21', 'IAU public information', 'space', 2, 0, '[{"canonical":"Orion","prior":25,"aliases":[]},{"canonical":"Ursa Major","prior":15,"aliases":["Great Bear"]},{"canonical":"Ursa Minor","prior":6,"aliases":["Little Bear"]},{"canonical":"Cassiopeia","prior":8,"aliases":[]},{"canonical":"Scorpius","prior":6,"aliases":["Scorpio"]},{"canonical":"Leo","prior":6,"aliases":[]},{"canonical":"Taurus","prior":4,"aliases":[]},{"canonical":"Gemini","prior":4,"aliases":[]},{"canonical":"Andromeda","prior":4,"aliases":[]},{"canonical":"Sagittarius","prior":3,"aliases":[]},{"canonical":"Cygnus","prior":3,"aliases":[]},{"canonical":"Pegasus","prior":3,"aliases":[]},{"canonical":"Crux","prior":3,"aliases":["Southern Cross"]},{"canonical":"Aries","prior":2,"aliases":[]},{"canonical":"Cancer","prior":2,"aliases":[]},{"canonical":"Virgo","prior":2,"aliases":[]},{"canonical":"Libra","prior":2,"aliases":[]},{"canonical":"Capricornus","prior":2,"aliases":["Capricorn"]},{"canonical":"Aquarius","prior":2,"aliases":[]},{"canonical":"Pisces","prior":2,"aliases":[]},{"canonical":"Lyra","prior":2,"aliases":[]},{"canonical":"Draco","prior":2,"aliases":[]},{"canonical":"Perseus","prior":2,"aliases":[]},{"canonical":"Centaurus","prior":2,"aliases":[]},{"canonical":"Canis Major","prior":2,"aliases":[]},{"canonical":"Hercules","prior":2,"aliases":[]},{"canonical":"Aquila","prior":1,"aliases":[]},{"canonical":"Auriga","prior":1,"aliases":[]},{"canonical":"Boötes","prior":1,"aliases":["Bootes"]},{"canonical":"Carina","prior":1,"aliases":[]},{"canonical":"Cepheus","prior":1,"aliases":[]},{"canonical":"Corvus","prior":1,"aliases":[]},{"canonical":"Delphinus","prior":1,"aliases":[]},{"canonical":"Hydra","prior":1,"aliases":[]},{"canonical":"Lupus","prior":1,"aliases":[]},{"canonical":"Ophiuchus","prior":1,"aliases":[]},{"canonical":"Phoenix","prior":1,"aliases":[]},{"canonical":"Canis Minor","prior":0.5,"aliases":[]},{"canonical":"Monoceros","prior":0.5,"aliases":[]},{"canonical":"Puppis","prior":0.5,"aliases":[]},{"canonical":"Vela","prior":0.5,"aliases":[]},{"canonical":"Sculptor","prior":0.5,"aliases":[]},{"canonical":"Fornax","prior":0.5,"aliases":[]},{"canonical":"Lepus","prior":0.5,"aliases":[]},{"canonical":"Columba","prior":0.5,"aliases":[]},{"canonical":"Eridanus","prior":0.5,"aliases":[]},{"canonical":"Corona Borealis","prior":0.5,"aliases":[]},{"canonical":"Serpens","prior":0.3,"aliases":[]},{"canonical":"Triangulum","prior":0.3,"aliases":[]},{"canonical":"Camelopardalis","prior":0.2,"aliases":[]},{"canonical":"Chamaeleon","prior":0.2,"aliases":[]},{"canonical":"Volans","prior":0.2,"aliases":[]},{"canonical":"Pavo","prior":0.2,"aliases":[]},{"canonical":"Tucana","prior":0.2,"aliases":[]},{"canonical":"Grus","prior":0.2,"aliases":[]}]', NULL);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-space-year', 'Name a country with more than 100 million people.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'The UN World Population Prospects 2024 median estimate puts 16 countries over 100 million, from India and China down to Vietnam. Iran sits just under the line. This sample list is not editorially verified.', 'https://population.un.org/wpp/', 'UN World Population Prospects 2024', '2026-11-21', 'United Nations public information', 'geography', 1, 0, '[{"canonical":"India","prior":30,"aliases":["Bharat","Republic of India"]},{"canonical":"China","prior":26,"aliases":["PRC","People''s Republic of China"]},{"canonical":"United States","prior":18,"aliases":["USA","US","U.S.","U.S.A.","America","United States of America"]},{"canonical":"Indonesia","prior":3,"aliases":[]},{"canonical":"Pakistan","prior":2,"aliases":[]},{"canonical":"Nigeria","prior":2,"aliases":[]},{"canonical":"Brazil","prior":6,"aliases":[]},{"canonical":"Bangladesh","prior":2,"aliases":[]},{"canonical":"Russia","prior":5,"aliases":["Russian Federation"]},{"canonical":"Ethiopia","prior":1,"aliases":[]},{"canonical":"Mexico","prior":3,"aliases":[]},{"canonical":"Japan","prior":4,"aliases":[]},{"canonical":"Philippines","prior":1,"aliases":[]},{"canonical":"Egypt","prior":1,"aliases":[]},{"canonical":"Democratic Republic of the Congo","prior":1,"aliases":["DR Congo","DRC","Congo-Kinshasa","Democratic Republic of Congo"]},{"canonical":"Vietnam","prior":1,"aliases":["Viet Nam"]}]', 'countries');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-earth-everest', 'Name a mountain higher than 8,000 metres.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Fourteen peaks rise above 8,000 metres, all in the Himalaya and the Karakoram. Reinhold Messner was the first to climb all of them, in 1986.', 'https://en.wikipedia.org/wiki/Eight-thousander', 'Wikipedia: Eight-thousander', '2026-11-21', 'CC BY-SA 4.0', 'geography', 2, 0, '[{"canonical":"Mount Everest","prior":40,"aliases":["Everest","Sagarmatha","Chomolungma"]},{"canonical":"K2","prior":20,"aliases":["Mount Godwin-Austen","Chhogori"]},{"canonical":"Kangchenjunga","prior":8,"aliases":["Kanchenjunga"]},{"canonical":"Annapurna","prior":6,"aliases":["Annapurna I"]},{"canonical":"Lhotse","prior":4,"aliases":[]},{"canonical":"Nanga Parbat","prior":4,"aliases":[]},{"canonical":"Makalu","prior":3,"aliases":[]},{"canonical":"Cho Oyu","prior":2,"aliases":[]},{"canonical":"Dhaulagiri","prior":2,"aliases":["Dhaulagiri I"]},{"canonical":"Manaslu","prior":2,"aliases":[]},{"canonical":"Gasherbrum I","prior":1,"aliases":["Hidden Peak","Gasherbrum 1"]},{"canonical":"Broad Peak","prior":1,"aliases":[]},{"canonical":"Gasherbrum II","prior":1,"aliases":["Gasherbrum 2"]},{"canonical":"Shishapangma","prior":1,"aliases":["Xixabangma"]}]', NULL);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-earth-seas', 'Name a noble gas.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'The noble gases are helium, neon, argon, krypton, xenon, radon, and oganesson, the last of which is only predicted to behave like the group. Pending verification.', 'https://www.rsc.org/periodic-table', 'Royal Society of Chemistry periodic table', '2026-11-21', 'Royal Society of Chemistry periodic table', 'science', 1, 0, '[{"canonical":"Helium","prior":10,"aliases":[]},{"canonical":"Neon","prior":10,"aliases":[]},{"canonical":"Argon","prior":6,"aliases":[]},{"canonical":"Krypton","prior":1,"aliases":[]},{"canonical":"Xenon","prior":1,"aliases":[]},{"canonical":"Radon","prior":1,"aliases":[]},{"canonical":"Oganesson","prior":1,"aliases":[]}]', 'elements');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-earth-oceans', 'Name a sea that touches Europe.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Europe touches about two dozen seas, from the Mediterranean to the Arctic. The Caspian is technically a lake, but it is called a sea and is counted here.', 'https://en.wikipedia.org/wiki/List_of_seas', 'Wikipedia: List of seas', '2026-11-21', 'CC BY-SA 4.0', 'geography', 2, 0, '[{"canonical":"Mediterranean Sea","prior":30,"aliases":["Mediterranean"]},{"canonical":"North Sea","prior":14,"aliases":[]},{"canonical":"Baltic Sea","prior":12,"aliases":["Baltic"]},{"canonical":"Black Sea","prior":12,"aliases":[]},{"canonical":"Adriatic Sea","prior":6,"aliases":["Adriatic"]},{"canonical":"Aegean Sea","prior":6,"aliases":["Aegean"]},{"canonical":"Caspian Sea","prior":3,"aliases":["Caspian"]},{"canonical":"Norwegian Sea","prior":2,"aliases":[]},{"canonical":"Irish Sea","prior":2,"aliases":[]},{"canonical":"Tyrrhenian Sea","prior":2,"aliases":["Tyrrhenian"]},{"canonical":"Ionian Sea","prior":2,"aliases":["Ionian"]},{"canonical":"Barents Sea","prior":2,"aliases":["Barents"]},{"canonical":"Ligurian Sea","prior":1,"aliases":["Ligurian"]},{"canonical":"Balearic Sea","prior":1,"aliases":[]},{"canonical":"White Sea","prior":1,"aliases":[]},{"canonical":"Celtic Sea","prior":1,"aliases":[]},{"canonical":"Sea of Azov","prior":1,"aliases":["Azov"]},{"canonical":"Sea of Marmara","prior":1,"aliases":["Marmara"]},{"canonical":"Alboran Sea","prior":0.5,"aliases":["Alboran"]},{"canonical":"Wadden Sea","prior":0.5,"aliases":[]},{"canonical":"Sea of the Hebrides","prior":0.2,"aliases":[]},{"canonical":"Kara Sea","prior":0.3,"aliases":[]},{"canonical":"Pechora Sea","prior":0.1,"aliases":[]}]', NULL);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-earth-trench', 'Name a river longer than 3,000 km.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'River lengths depend on where the source is drawn, so lists disagree. The Nile and the Amazon trade first place depending on the survey.', 'https://en.wikipedia.org/wiki/List_of_rivers_by_length', 'Wikipedia: List of rivers by length', '2026-11-21', 'CC BY-SA 4.0', 'geography', 2, 0, '[{"canonical":"Nile","prior":25,"aliases":["River Nile","Nile River"]},{"canonical":"Amazon","prior":22,"aliases":["Amazon River"]},{"canonical":"Yangtze","prior":10,"aliases":["Chang Jiang","Yangtze River"]},{"canonical":"Mississippi","prior":10,"aliases":["Mississippi River"]},{"canonical":"Yellow River","prior":4,"aliases":["Huang He"]},{"canonical":"Congo","prior":4,"aliases":["Congo River","Zaire River"]},{"canonical":"Mekong","prior":4,"aliases":[]},{"canonical":"Volga","prior":4,"aliases":[]},{"canonical":"Missouri","prior":3,"aliases":[]},{"canonical":"Indus","prior":3,"aliases":[]},{"canonical":"Yenisei","prior":2,"aliases":[]},{"canonical":"Ob","prior":2,"aliases":[]},{"canonical":"Paraná","prior":2,"aliases":["Parana"]},{"canonical":"Niger","prior":2,"aliases":["Niger River"]},{"canonical":"Brahmaputra","prior":2,"aliases":[]},{"canonical":"Amur","prior":1,"aliases":[]},{"canonical":"Lena","prior":1,"aliases":[]},{"canonical":"Mackenzie","prior":1,"aliases":[]},{"canonical":"Salween","prior":1,"aliases":[]},{"canonical":"Rio Grande","prior":1,"aliases":[]},{"canonical":"Yukon","prior":1,"aliases":[]},{"canonical":"Irtysh","prior":1,"aliases":[]},{"canonical":"Purus","prior":0.5,"aliases":[]},{"canonical":"Madeira","prior":0.5,"aliases":[]}]', NULL);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-earth-peaks', 'Name a chemical element discovered after 1900.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Discovery years are conventional and a few were disputed for decades. This list starts with europium (1901) and runs through oganesson, and it leaves out radon, which was identified in 1900. Pending verification.', 'https://www.rsc.org/periodic-table', 'Royal Society of Chemistry periodic table', '2026-11-21', 'Royal Society of Chemistry periodic table', 'science', 2, 0, '[{"canonical":"Europium","prior":1,"aliases":[]},{"canonical":"Lutetium","prior":1,"aliases":[]},{"canonical":"Protactinium","prior":1,"aliases":[]},{"canonical":"Hafnium","prior":1,"aliases":[]},{"canonical":"Rhenium","prior":1,"aliases":[]},{"canonical":"Technetium","prior":1,"aliases":[]},{"canonical":"Francium","prior":1,"aliases":[]},{"canonical":"Astatine","prior":1,"aliases":[]},{"canonical":"Promethium","prior":1,"aliases":[]},{"canonical":"Neptunium","prior":1,"aliases":[]},{"canonical":"Plutonium","prior":16,"aliases":[]},{"canonical":"Americium","prior":1,"aliases":[]},{"canonical":"Curium","prior":1,"aliases":[]},{"canonical":"Berkelium","prior":1,"aliases":[]},{"canonical":"Californium","prior":1,"aliases":[]},{"canonical":"Einsteinium","prior":4,"aliases":[]},{"canonical":"Fermium","prior":1,"aliases":[]},{"canonical":"Mendelevium","prior":1,"aliases":[]},{"canonical":"Nobelium","prior":1,"aliases":[]},{"canonical":"Lawrencium","prior":1,"aliases":[]},{"canonical":"Rutherfordium","prior":1,"aliases":[]},{"canonical":"Dubnium","prior":1,"aliases":[]},{"canonical":"Seaborgium","prior":1,"aliases":[]},{"canonical":"Bohrium","prior":1,"aliases":[]},{"canonical":"Hassium","prior":1,"aliases":[]},{"canonical":"Meitnerium","prior":1,"aliases":[]},{"canonical":"Darmstadtium","prior":1,"aliases":[]},{"canonical":"Roentgenium","prior":1,"aliases":[]},{"canonical":"Copernicium","prior":1,"aliases":[]},{"canonical":"Nihonium","prior":1,"aliases":[]},{"canonical":"Flerovium","prior":1,"aliases":[]},{"canonical":"Moscovium","prior":1,"aliases":[]},{"canonical":"Livermorium","prior":1,"aliases":[]},{"canonical":"Tennessine","prior":1,"aliases":[]},{"canonical":"Oganesson","prior":1,"aliases":[]}]', 'elements');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-body-bones', 'Name a bone in the human body.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'An adult skeleton has 206 bones. The femur is the longest. The stapes in the middle ear is the smallest, about 3 mm long.', 'https://en.wikipedia.org/wiki/List_of_bones_of_the_human_skeleton', 'Wikipedia: List of bones of the human skeleton', '2026-11-21', 'CC BY-SA 4.0', 'body', 1, 0, '[{"canonical":"Femur","prior":25,"aliases":["Thigh bone","Thighbone"]},{"canonical":"Tibia","prior":8,"aliases":["Shin bone","Shinbone"]},{"canonical":"Humerus","prior":8,"aliases":[]},{"canonical":"Rib","prior":8,"aliases":["Ribs"]},{"canonical":"Skull","prior":6,"aliases":["Cranium"]},{"canonical":"Fibula","prior":5,"aliases":[]},{"canonical":"Radius","prior":5,"aliases":[]},{"canonical":"Ulna","prior":5,"aliases":[]},{"canonical":"Clavicle","prior":5,"aliases":["Collarbone","Collar bone"]},{"canonical":"Scapula","prior":4,"aliases":["Shoulder blade"]},{"canonical":"Sternum","prior":4,"aliases":["Breastbone"]},{"canonical":"Patella","prior":4,"aliases":["Kneecap","Knee cap"]},{"canonical":"Mandible","prior":4,"aliases":["Jawbone","Jaw bone","Jaw"]},{"canonical":"Pelvis","prior":3,"aliases":["Hip bone","Hipbone"]},{"canonical":"Vertebra","prior":3,"aliases":["Vertebrae","Spine"]},{"canonical":"Coccyx","prior":2,"aliases":["Tailbone","Tail bone"]},{"canonical":"Stapes","prior":2,"aliases":["Stirrup"]},{"canonical":"Incus","prior":1,"aliases":["Anvil"]},{"canonical":"Malleus","prior":1,"aliases":["Hammer"]},{"canonical":"Maxilla","prior":1,"aliases":[]},{"canonical":"Sacrum","prior":1,"aliases":[]},{"canonical":"Hyoid","prior":1,"aliases":["Hyoid bone"]},{"canonical":"Calcaneus","prior":1,"aliases":["Heel bone"]},{"canonical":"Phalanx","prior":1,"aliases":["Phalanges"]},{"canonical":"Talus","prior":0.5,"aliases":[]},{"canonical":"Carpal","prior":0.5,"aliases":["Carpals"]},{"canonical":"Metacarpal","prior":0.5,"aliases":["Metacarpals"]},{"canonical":"Metatarsal","prior":0.5,"aliases":["Metatarsals"]},{"canonical":"Scaphoid","prior":0.5,"aliases":[]},{"canonical":"Occipital bone","prior":0.5,"aliases":["Occipital"]},{"canonical":"Parietal bone","prior":0.5,"aliases":["Parietal"]},{"canonical":"Temporal bone","prior":0.5,"aliases":["Temporal"]},{"canonical":"Frontal bone","prior":0.5,"aliases":["Frontal"]},{"canonical":"Zygomatic bone","prior":0.5,"aliases":["Cheekbone","Zygomatic"]},{"canonical":"Nasal bone","prior":0.5,"aliases":[]},{"canonical":"Sphenoid","prior":0.3,"aliases":[]},{"canonical":"Ethmoid","prior":0.3,"aliases":[]},{"canonical":"Lacrimal bone","prior":0.3,"aliases":["Lacrimal"]},{"canonical":"Vomer","prior":0.3,"aliases":[]},{"canonical":"Palatine bone","prior":0.3,"aliases":["Palatine"]},{"canonical":"Atlas","prior":0.3,"aliases":[]},{"canonical":"Axis","prior":0.3,"aliases":[]},{"canonical":"Ilium","prior":0.4,"aliases":[]},{"canonical":"Ischium","prior":0.3,"aliases":[]},{"canonical":"Pubis","prior":0.3,"aliases":[]},{"canonical":"Lunate","prior":0.3,"aliases":[]},{"canonical":"Navicular","prior":0.3,"aliases":[]},{"canonical":"Cuboid","prior":0.3,"aliases":[]},{"canonical":"Cuneiform","prior":0.2,"aliases":[]},{"canonical":"Trapezium","prior":0.2,"aliases":[]},{"canonical":"Trapezoid","prior":0.2,"aliases":[]},{"canonical":"Hamate","prior":0.2,"aliases":[]},{"canonical":"Pisiform","prior":0.2,"aliases":[]},{"canonical":"Capitate","prior":0.2,"aliases":[]},{"canonical":"Triquetrum","prior":0.2,"aliases":[]}]', NULL);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-body-lungs', 'Name a halogen.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Group 17 is fluorine, chlorine, bromine, iodine, astatine, and tennessine. Pending verification.', 'https://www.rsc.org/periodic-table', 'Royal Society of Chemistry periodic table', '2026-11-21', 'Royal Society of Chemistry periodic table', 'science', 1, 0, '[{"canonical":"Fluorine","prior":8,"aliases":[]},{"canonical":"Chlorine","prior":8,"aliases":[]},{"canonical":"Bromine","prior":1,"aliases":[]},{"canonical":"Iodine","prior":6,"aliases":[]},{"canonical":"Astatine","prior":1,"aliases":[]},{"canonical":"Tennessine","prior":1,"aliases":[]}]', 'elements');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-body-counts', 'Name an organ of the human body.', 'name_one', NULL, 'lower', NULL, '[]', '[]', 'Anatomists count roughly 78 organs, depending on how they are grouped. The skin is the largest by area and by weight.', 'https://en.wikipedia.org/wiki/List_of_organs_of_the_human_body', 'Wikipedia: List of organs of the human body', '2026-11-21', 'CC BY-SA 4.0', 'body', 1, 0, '[{"canonical":"Heart","prior":30,"aliases":[]},{"canonical":"Brain","prior":18,"aliases":[]},{"canonical":"Lung","prior":12,"aliases":["Lungs"]},{"canonical":"Liver","prior":10,"aliases":[]},{"canonical":"Kidney","prior":8,"aliases":["Kidneys"]},{"canonical":"Stomach","prior":6,"aliases":[]},{"canonical":"Skin","prior":4,"aliases":[]},{"canonical":"Pancreas","prior":3,"aliases":[]},{"canonical":"Intestine","prior":3,"aliases":["Intestines","Small intestine","Large intestine","Gut","Bowel"]},{"canonical":"Spleen","prior":2,"aliases":[]},{"canonical":"Bladder","prior":2,"aliases":["Urinary bladder"]},{"canonical":"Eye","prior":1.5,"aliases":["Eyes"]},{"canonical":"Gallbladder","prior":1,"aliases":["Gall bladder"]},{"canonical":"Appendix","prior":1,"aliases":[]},{"canonical":"Thyroid","prior":1,"aliases":["Thyroid gland"]},{"canonical":"Colon","prior":0.5,"aliases":[]},{"canonical":"Tongue","prior":0.5,"aliases":[]},{"canonical":"Oesophagus","prior":0.5,"aliases":["Esophagus","Gullet"]},{"canonical":"Uterus","prior":0.5,"aliases":["Womb"]},{"canonical":"Ovary","prior":0.5,"aliases":["Ovaries"]},{"canonical":"Prostate","prior":0.5,"aliases":["Prostate gland"]},{"canonical":"Testis","prior":0.3,"aliases":["Testes","Testicle","Testicles"]},{"canonical":"Thymus","prior":0.3,"aliases":[]},{"canonical":"Adrenal gland","prior":0.3,"aliases":["Adrenal glands","Adrenals"]},{"canonical":"Pituitary gland","prior":0.3,"aliases":["Pituitary"]},{"canonical":"Pineal gland","prior":0.2,"aliases":["Pineal"]},{"canonical":"Larynx","prior":0.3,"aliases":["Voice box"]},{"canonical":"Trachea","prior":0.3,"aliases":["Windpipe"]},{"canonical":"Diaphragm","prior":0.3,"aliases":[]},{"canonical":"Tonsil","prior":0.3,"aliases":["Tonsils"]}]', NULL);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-body-neurons', 'Name a part of the human brain.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'The adult brain holds about 86 billion neurons. The cerebellum is about a tenth of the brain''s volume but contains more than half of its neurons.', 'https://en.wikipedia.org/wiki/Human_brain', 'Wikipedia: Human brain', '2026-11-21', 'CC BY-SA 4.0', 'body', 2, 0, '[{"canonical":"Cerebellum","prior":14,"aliases":[]},{"canonical":"Cerebrum","prior":12,"aliases":[]},{"canonical":"Hippocampus","prior":10,"aliases":[]},{"canonical":"Frontal lobe","prior":10,"aliases":[]},{"canonical":"Brainstem","prior":8,"aliases":["Brain stem"]},{"canonical":"Amygdala","prior":8,"aliases":[]},{"canonical":"Hypothalamus","prior":6,"aliases":[]},{"canonical":"Thalamus","prior":5,"aliases":[]},{"canonical":"Medulla oblongata","prior":4,"aliases":["Medulla"]},{"canonical":"Prefrontal cortex","prior":4,"aliases":[]},{"canonical":"Cerebral cortex","prior":4,"aliases":["Cortex"]},{"canonical":"Corpus callosum","prior":3,"aliases":[]},{"canonical":"Temporal lobe","prior":3,"aliases":[]},{"canonical":"Parietal lobe","prior":3,"aliases":[]},{"canonical":"Occipital lobe","prior":3,"aliases":[]},{"canonical":"Pituitary gland","prior":3,"aliases":["Pituitary"]},{"canonical":"Pons","prior":2,"aliases":[]},{"canonical":"Pineal gland","prior":2,"aliases":["Pineal"]},{"canonical":"Basal ganglia","prior":1,"aliases":[]},{"canonical":"Midbrain","prior":1,"aliases":["Mesencephalon"]},{"canonical":"Limbic system","prior":1,"aliases":[]},{"canonical":"Broca''s area","prior":1,"aliases":["Brocas area"]},{"canonical":"Wernicke''s area","prior":0.5,"aliases":["Wernickes area"]},{"canonical":"Motor cortex","prior":0.5,"aliases":[]},{"canonical":"Insula","prior":0.3,"aliases":[]},{"canonical":"Striatum","prior":0.3,"aliases":[]},{"canonical":"Substantia nigra","prior":0.3,"aliases":[]},{"canonical":"Ventricles","prior":0.3,"aliases":["Ventricle"]},{"canonical":"Fornix","prior":0.2,"aliases":[]},{"canonical":"Caudate nucleus","prior":0.2,"aliases":[]},{"canonical":"Putamen","prior":0.2,"aliases":[]},{"canonical":"Globus pallidus","prior":0.2,"aliases":[]}]', NULL);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-body-gut', 'Name an African country with more than 50 million people.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Using the UN 2024 estimates, nine African countries are at or above 50 million: Nigeria, Ethiopia, Egypt, DR Congo, Tanzania, South Africa, Kenya, Sudan, and Uganda. Algeria sits just below. Pending verification.', 'https://population.un.org/wpp/', 'UN World Population Prospects 2024', '2026-11-21', 'United Nations public information', 'geography', 2, 0, '[{"canonical":"Nigeria","prior":24,"aliases":[]},{"canonical":"Ethiopia","prior":8,"aliases":[]},{"canonical":"Egypt","prior":10,"aliases":[]},{"canonical":"Democratic Republic of the Congo","prior":4,"aliases":["DR Congo","DRC","Congo-Kinshasa","Democratic Republic of Congo"]},{"canonical":"Tanzania","prior":3,"aliases":[]},{"canonical":"South Africa","prior":6,"aliases":[]},{"canonical":"Kenya","prior":3,"aliases":[]},{"canonical":"Sudan","prior":1,"aliases":[]},{"canonical":"Uganda","prior":1,"aliases":[]}]', 'countries');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-inv-order', 'Name an invention from the 1800s.', 'name_one', NULL, 'lower', NULL, '[]', '[]', 'Bell patented the telephone in 1876 and Edison''s practical light bulb followed in 1879. Earlier inventors made working versions of both, which is why the dates are argued over.', 'https://en.wikipedia.org/wiki/Timeline_of_historic_inventions', 'Wikipedia: Timeline of historic inventions', '2026-11-21', 'CC BY-SA 4.0', 'history', 2, 0, '[{"canonical":"Telephone","prior":25,"aliases":["Phone"]},{"canonical":"Light bulb","prior":18,"aliases":["Lightbulb","Incandescent light bulb","Electric light"]},{"canonical":"Telegraph","prior":6,"aliases":["Electric telegraph"]},{"canonical":"Camera","prior":6,"aliases":["Photograph","Photography"]},{"canonical":"Automobile","prior":6,"aliases":["Car","Motor car"]},{"canonical":"Steam locomotive","prior":4,"aliases":["Locomotive","Steam train","Railway"]},{"canonical":"Bicycle","prior":3,"aliases":["Bike"]},{"canonical":"Phonograph","prior":3,"aliases":[]},{"canonical":"Radio","prior":3,"aliases":[]},{"canonical":"Typewriter","prior":2,"aliases":[]},{"canonical":"Dynamite","prior":2,"aliases":[]},{"canonical":"Sewing machine","prior":1.5,"aliases":[]},{"canonical":"Morse code","prior":1,"aliases":[]},{"canonical":"Stethoscope","prior":1,"aliases":[]},{"canonical":"Internal combustion engine","prior":1,"aliases":["Petrol engine","Gasoline engine"]},{"canonical":"Electric motor","prior":1,"aliases":[]},{"canonical":"Kinetoscope","prior":1,"aliases":["Motion picture camera","Film camera","Movie camera"]},{"canonical":"Diesel engine","prior":0.5,"aliases":[]},{"canonical":"X-ray machine","prior":0.5,"aliases":["X-ray","X-rays"]},{"canonical":"Gramophone","prior":0.5,"aliases":[]},{"canonical":"Refrigerator","prior":0.5,"aliases":["Fridge"]},{"canonical":"Safety elevator","prior":0.5,"aliases":["Elevator","Lift"]},{"canonical":"Friction match","prior":0.5,"aliases":["Match","Matches"]},{"canonical":"Revolver","prior":0.5,"aliases":[]},{"canonical":"Pasteurisation","prior":0.5,"aliases":["Pasteurization"]},{"canonical":"Zip","prior":0.3,"aliases":["Zipper","Clasp locker"]},{"canonical":"Postage stamp","prior":0.3,"aliases":["Stamp","Penny Black"]},{"canonical":"Blue jeans","prior":0.3,"aliases":["Jeans"]},{"canonical":"Fountain pen","prior":0.3,"aliases":[]},{"canonical":"Escalator","prior":0.2,"aliases":[]},{"canonical":"Dishwasher","prior":0.2,"aliases":[]},{"canonical":"Paper clip","prior":0.2,"aliases":["Paperclip"]},{"canonical":"Safety pin","prior":0.2,"aliases":[]},{"canonical":"Barbed wire","prior":0.2,"aliases":[]},{"canonical":"Ferris wheel","prior":0.2,"aliases":[]},{"canonical":"Stapler","prior":0.2,"aliases":[]}]', NULL);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-inv-piano', 'Name a musical instrument with strings.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'A piano is a string instrument too: each key throws a felt hammer at a stretched steel string. A concert grand has about 230 of them.', 'https://en.wikipedia.org/wiki/List_of_string_instruments', 'Wikipedia: List of string instruments', '2026-11-21', 'CC BY-SA 4.0', 'culture', 1, 0, '[{"canonical":"Guitar","prior":35,"aliases":["Acoustic guitar","Electric guitar"]},{"canonical":"Violin","prior":18,"aliases":["Fiddle"]},{"canonical":"Cello","prior":8,"aliases":["Violoncello"]},{"canonical":"Harp","prior":7,"aliases":[]},{"canonical":"Piano","prior":4,"aliases":["Pianoforte"]},{"canonical":"Double bass","prior":4,"aliases":["Bass","Upright bass","Contrabass","Bass guitar"]},{"canonical":"Viola","prior":4,"aliases":[]},{"canonical":"Ukulele","prior":4,"aliases":["Uke"]},{"canonical":"Banjo","prior":3,"aliases":[]},{"canonical":"Mandolin","prior":2,"aliases":[]},{"canonical":"Sitar","prior":2,"aliases":[]},{"canonical":"Lute","prior":1,"aliases":[]},{"canonical":"Harpsichord","prior":1,"aliases":[]},{"canonical":"Zither","prior":0.5,"aliases":[]},{"canonical":"Lyre","prior":0.5,"aliases":[]},{"canonical":"Balalaika","prior":0.5,"aliases":[]},{"canonical":"Dulcimer","prior":0.3,"aliases":[]},{"canonical":"Koto","prior":0.3,"aliases":[]},{"canonical":"Erhu","prior":0.3,"aliases":[]},{"canonical":"Sarod","prior":0.3,"aliases":[]},{"canonical":"Veena","prior":0.3,"aliases":[]},{"canonical":"Oud","prior":0.3,"aliases":[]},{"canonical":"Bouzouki","prior":0.3,"aliases":[]},{"canonical":"Shamisen","prior":0.3,"aliases":[]},{"canonical":"Clavichord","prior":0.2,"aliases":[]},{"canonical":"Hurdy-gurdy","prior":0.2,"aliases":["Hurdy gurdy"]},{"canonical":"Pipa","prior":0.2,"aliases":[]},{"canonical":"Charango","prior":0.2,"aliases":[]},{"canonical":"Santoor","prior":0.2,"aliases":["Santur"]},{"canonical":"Tanpura","prior":0.2,"aliases":["Tambura"]},{"canonical":"Guzheng","prior":0.2,"aliases":[]},{"canonical":"Kora","prior":0.2,"aliases":[]}]', NULL);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-inv-towers', 'Name an alkali metal.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'The alkali metals are lithium, sodium, potassium, rubidium, caesium, and francium. Hydrogen is left off this list. Pending verification.', 'https://www.rsc.org/periodic-table', 'Royal Society of Chemistry periodic table', '2026-11-21', 'Royal Society of Chemistry periodic table', 'science', 1, 0, '[{"canonical":"Lithium","prior":6,"aliases":[]},{"canonical":"Sodium","prior":8,"aliases":[]},{"canonical":"Potassium","prior":8,"aliases":[]},{"canonical":"Rubidium","prior":1,"aliases":[]},{"canonical":"Cesium","prior":1,"aliases":["Caesium"]},{"canonical":"Francium","prior":1,"aliases":[]}]', 'elements');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-inv-empire', 'Name a programming language.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Fortran, from 1957, is usually counted as the first widely used high-level language. HTML and CSS describe pages rather than programs, so they are not on the list.', 'https://en.wikipedia.org/wiki/List_of_programming_languages', 'Wikipedia: List of programming languages', '2026-11-21', 'CC BY-SA 4.0', 'technology', 1, 0, '[{"canonical":"Python","prior":30,"aliases":[]},{"canonical":"Java","prior":15,"aliases":[]},{"canonical":"JavaScript","prior":12,"aliases":["JS","Java Script"]},{"canonical":"C++","prior":8,"aliases":["CPP","C plus plus"]},{"canonical":"C","prior":6,"aliases":[]},{"canonical":"C#","prior":4,"aliases":["C Sharp","CSharp"]},{"canonical":"Ruby","prior":2,"aliases":[]},{"canonical":"PHP","prior":2,"aliases":[]},{"canonical":"Swift","prior":2,"aliases":[]},{"canonical":"Go","prior":1.5,"aliases":["Golang"]},{"canonical":"Rust","prior":1.5,"aliases":[]},{"canonical":"Kotlin","prior":1,"aliases":[]},{"canonical":"R","prior":1,"aliases":[]},{"canonical":"TypeScript","prior":1,"aliases":["TS","Type Script"]},{"canonical":"SQL","prior":1,"aliases":[]},{"canonical":"MATLAB","prior":0.5,"aliases":[]},{"canonical":"Perl","prior":0.5,"aliases":[]},{"canonical":"Fortran","prior":0.5,"aliases":[]},{"canonical":"COBOL","prior":0.5,"aliases":[]},{"canonical":"BASIC","prior":0.5,"aliases":[]},{"canonical":"Assembly","prior":0.5,"aliases":["Assembly language","Assembler"]},{"canonical":"Lisp","prior":0.4,"aliases":[]},{"canonical":"Haskell","prior":0.4,"aliases":[]},{"canonical":"Scala","prior":0.3,"aliases":[]},{"canonical":"Pascal","prior":0.3,"aliases":[]},{"canonical":"Lua","prior":0.3,"aliases":[]},{"canonical":"Dart","prior":0.3,"aliases":[]},{"canonical":"Julia","prior":0.3,"aliases":[]},{"canonical":"Scratch","prior":0.3,"aliases":[]},{"canonical":"Objective-C","prior":0.3,"aliases":["Objective C","ObjC"]},{"canonical":"Visual Basic","prior":0.3,"aliases":["VB","VB.NET"]},{"canonical":"Bash","prior":0.2,"aliases":["Shell"]},{"canonical":"Prolog","prior":0.2,"aliases":[]},{"canonical":"Erlang","prior":0.2,"aliases":[]},{"canonical":"Elixir","prior":0.2,"aliases":[]},{"canonical":"OCaml","prior":0.1,"aliases":[]},{"canonical":"Smalltalk","prior":0.1,"aliases":[]},{"canonical":"Ada","prior":0.1,"aliases":[]},{"canonical":"Clojure","prior":0.1,"aliases":[]},{"canonical":"F#","prior":0.1,"aliases":["F Sharp"]},{"canonical":"Zig","prior":0.1,"aliases":[]},{"canonical":"Groovy","prior":0.1,"aliases":[]},{"canonical":"Racket","prior":0.1,"aliases":[]},{"canonical":"Scheme","prior":0.1,"aliases":[]},{"canonical":"APL","prior":0.05,"aliases":[]},{"canonical":"Simula","prior":0.05,"aliases":[]},{"canonical":"ALGOL","prior":0.05,"aliases":[]}]', NULL);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-inv-first', 'Name a country with fewer than 1 million people.', 'name_one', NULL, 'lower', NULL, '[]', '[]', 'A 2023 UN grouping of member states under 1 million runs from Fiji and Iceland through Tuvalu. This sample also accepts Vatican City, an observer state, and Vanuatu. Pending verification.', 'https://population.un.org/wpp/', 'United Nations population estimates, via UN member groupings', '2026-11-21', 'United Nations public information', 'geography', 2, 0, '[{"canonical":"Iceland","prior":12,"aliases":[]},{"canonical":"Luxembourg","prior":8,"aliases":[]},{"canonical":"Malta","prior":4,"aliases":[]},{"canonical":"Brunei","prior":2,"aliases":["Brunei Darussalam"]},{"canonical":"Bahamas","prior":2,"aliases":["The Bahamas"]},{"canonical":"Maldives","prior":3,"aliases":[]},{"canonical":"Belize","prior":1,"aliases":[]},{"canonical":"Barbados","prior":2,"aliases":[]},{"canonical":"Fiji","prior":2,"aliases":[]},{"canonical":"Guyana","prior":1,"aliases":[]},{"canonical":"Suriname","prior":1,"aliases":[]},{"canonical":"Bhutan","prior":2,"aliases":[]},{"canonical":"Comoros","prior":1,"aliases":[]},{"canonical":"Solomon Islands","prior":1,"aliases":[]},{"canonical":"Cabo Verde","prior":1,"aliases":["Cape Verde"]},{"canonical":"Vanuatu","prior":1,"aliases":[]},{"canonical":"Samoa","prior":1,"aliases":[]},{"canonical":"Andorra","prior":2,"aliases":[]},{"canonical":"Monaco","prior":3,"aliases":[]},{"canonical":"Liechtenstein","prior":2,"aliases":[]},{"canonical":"San Marino","prior":1,"aliases":[]},{"canonical":"Vatican City","prior":4,"aliases":["Holy See"]},{"canonical":"Palau","prior":1,"aliases":[]},{"canonical":"Nauru","prior":1,"aliases":[]},{"canonical":"Tuvalu","prior":1,"aliases":[]},{"canonical":"Kiribati","prior":1,"aliases":[]},{"canonical":"Tonga","prior":1,"aliases":[]},{"canonical":"Seychelles","prior":1,"aliases":[]},{"canonical":"Grenada","prior":1,"aliases":[]},{"canonical":"Dominica","prior":1,"aliases":[]},{"canonical":"Saint Lucia","prior":1,"aliases":[]},{"canonical":"Antigua and Barbuda","prior":1,"aliases":[]},{"canonical":"Saint Kitts and Nevis","prior":1,"aliases":[]},{"canonical":"Saint Vincent and the Grenadines","prior":1,"aliases":["Saint Vincent and the Grenadines"]},{"canonical":"Marshall Islands","prior":1,"aliases":[]},{"canonical":"Micronesia","prior":1,"aliases":["Federated States of Micronesia"]},{"canonical":"Sao Tome and Principe","prior":1,"aliases":["São Tomé and Príncipe"]},{"canonical":"Montenegro","prior":2,"aliases":[]}]', 'countries');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-land-pyramid', 'Name one of the New Seven Wonders of the World.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'The list came from a public vote run by the New7Wonders Foundation and announced in 2007. The Great Pyramid of Giza, the only ancient wonder still standing, was given an honorary place outside the seven.', 'https://en.wikipedia.org/wiki/New_7_Wonders_of_the_World', 'Wikipedia: New 7 Wonders of the World', '2026-11-21', 'CC BY-SA 4.0', 'landmarks', 2, 0, '[{"canonical":"Great Wall of China","prior":25,"aliases":["Great Wall","The Great Wall"]},{"canonical":"Taj Mahal","prior":18,"aliases":[]},{"canonical":"Machu Picchu","prior":14,"aliases":[]},{"canonical":"Colosseum","prior":14,"aliases":["Coliseum","Roman Colosseum"]},{"canonical":"Christ the Redeemer","prior":12,"aliases":["Cristo Redentor"]},{"canonical":"Petra","prior":8,"aliases":[]},{"canonical":"Chichén Itzá","prior":8,"aliases":["Chichen Itza"]}]', NULL);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-land-older', 'Name a member of the Group of Seven.', 'name_one', NULL, 'lower', NULL, '[]', '[]', 'The G7 is Canada, France, Germany, Italy, Japan, the United Kingdom, and the United States. The European Union attends but is not a country on this list. Pending verification.', 'https://www.international.gc.ca/world-monde/international_relations-relations_internationales/g7/index.aspx', 'Government of Canada: G7', '2026-11-21', 'Government of Canada public information', 'geography', 1, 0, '[{"canonical":"Canada","prior":4,"aliases":[]},{"canonical":"France","prior":8,"aliases":[]},{"canonical":"Germany","prior":4,"aliases":[]},{"canonical":"Italy","prior":4,"aliases":[]},{"canonical":"Japan","prior":4,"aliases":[]},{"canonical":"United Kingdom","prior":4,"aliases":["UK","Britain"]},{"canonical":"United States","prior":8,"aliases":["USA","US","America"]}]', 'countries');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-land-timeline', 'Name a city that has hosted the Summer Olympics.', 'name_one', NULL, 'lower', NULL, '[]', '[]', 'Twenty-three cities have hosted the Summer Games. London has hosted three times, in 1908, 1948 and 2012. Paris and Los Angeles will both reach three with 2024 and 2028.', 'https://en.wikipedia.org/wiki/List_of_Olympic_Games_host_cities', 'Wikipedia: List of Olympic Games host cities', '2026-11-21', 'CC BY-SA 4.0', 'culture', 2, 0, '[{"canonical":"London","prior":20,"aliases":[]},{"canonical":"Paris","prior":12,"aliases":[]},{"canonical":"Beijing","prior":10,"aliases":["Peking"]},{"canonical":"Tokyo","prior":10,"aliases":[]},{"canonical":"Los Angeles","prior":8,"aliases":["LA","L.A."]},{"canonical":"Athens","prior":8,"aliases":[]},{"canonical":"Rio de Janeiro","prior":6,"aliases":["Rio"]},{"canonical":"Sydney","prior":6,"aliases":[]},{"canonical":"Barcelona","prior":4,"aliases":[]},{"canonical":"Atlanta","prior":3,"aliases":[]},{"canonical":"Seoul","prior":3,"aliases":[]},{"canonical":"Moscow","prior":2,"aliases":[]},{"canonical":"Montreal","prior":2,"aliases":["Montréal"]},{"canonical":"Munich","prior":2,"aliases":["München"]},{"canonical":"Mexico City","prior":2,"aliases":[]},{"canonical":"Rome","prior":2,"aliases":[]},{"canonical":"Berlin","prior":2,"aliases":[]},{"canonical":"Melbourne","prior":1,"aliases":[]},{"canonical":"Helsinki","prior":1,"aliases":[]},{"canonical":"Amsterdam","prior":1,"aliases":[]},{"canonical":"Stockholm","prior":1,"aliases":[]},{"canonical":"Antwerp","prior":0.5,"aliases":[]},{"canonical":"St. Louis","prior":0.5,"aliases":["St Louis","Saint Louis"]}]', NULL);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-land-liberty', 'Name a skyscraper taller than 400 metres, measured to its architectural top.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Burj Khalifa has held the record since 2010 at 828 metres. The Empire State Building''s roof is 381 metres, so its antenna does not count here.', 'https://www.skyscrapercenter.com/buildings', 'Council on Tall Buildings and Urban Habitat', '2026-11-21', 'CTBUH public listing', 'landmarks', 3, 0, '[{"canonical":"Burj Khalifa","prior":40,"aliases":[]},{"canonical":"One World Trade Center","prior":8,"aliases":["Freedom Tower","1 WTC","One WTC"]},{"canonical":"Shanghai Tower","prior":8,"aliases":[]},{"canonical":"Taipei 101","prior":6,"aliases":[]},{"canonical":"Petronas Towers","prior":6,"aliases":["Petronas Twin Towers","Petronas Tower"]},{"canonical":"Willis Tower","prior":4,"aliases":["Sears Tower"]},{"canonical":"Abraj Al-Bait","prior":2,"aliases":["Makkah Royal Clock Tower","Mecca Clock Tower","Abraj Al Bait"]},{"canonical":"Lotte World Tower","prior":1.5,"aliases":[]},{"canonical":"Ping An Finance Center","prior":1,"aliases":["Ping An Finance Centre"]},{"canonical":"Merdeka 118","prior":1,"aliases":[]},{"canonical":"Shanghai World Financial Center","prior":0.8,"aliases":[]},{"canonical":"International Commerce Centre","prior":0.5,"aliases":["ICC Hong Kong"]},{"canonical":"Central Park Tower","prior":0.5,"aliases":[]},{"canonical":"Lakhta Center","prior":0.5,"aliases":[]},{"canonical":"Goldin Finance 117","prior":0.3,"aliases":[]},{"canonical":"Guangzhou CTF Finance Centre","prior":0.3,"aliases":[]},{"canonical":"Tianjin CTF Finance Centre","prior":0.3,"aliases":[]},{"canonical":"CITIC Tower","prior":0.3,"aliases":["China Zun"]},{"canonical":"Landmark 81","prior":0.3,"aliases":["Vincom Landmark 81"]},{"canonical":"432 Park Avenue","prior":0.3,"aliases":[]},{"canonical":"Jin Mao Tower","prior":0.3,"aliases":[]},{"canonical":"Two International Finance Centre","prior":0.3,"aliases":["Two IFC","2 IFC"]},{"canonical":"Trump International Hotel and Tower","prior":0.2,"aliases":["Trump Tower Chicago"]},{"canonical":"Wuhan Greenland Center","prior":0.2,"aliases":[]}]', NULL);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-land-statues', 'Name a country with an area greater than 1 million square kilometres.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Total area, land plus inland water, from the standard country-area tables. Twenty-nine countries clear 1 million km². Tanzania and Nigeria fall short. Greenland is not counted here because it is not a country. Pending verification.', 'https://en.wikipedia.org/wiki/List_of_countries_and_dependencies_by_area', 'Wikipedia: List of countries and dependencies by area', '2026-11-21', 'CC BY-SA 4.0', 'geography', 2, 0, '[{"canonical":"Russia","prior":16,"aliases":["Russian Federation"]},{"canonical":"Canada","prior":14,"aliases":[]},{"canonical":"China","prior":12,"aliases":["PRC","People''s Republic of China"]},{"canonical":"United States","prior":12,"aliases":["USA","US","America","United States of America"]},{"canonical":"Brazil","prior":8,"aliases":[]},{"canonical":"Australia","prior":8,"aliases":[]},{"canonical":"India","prior":6,"aliases":["Bharat"]},{"canonical":"Argentina","prior":3,"aliases":[]},{"canonical":"Kazakhstan","prior":2,"aliases":[]},{"canonical":"Algeria","prior":2,"aliases":[]},{"canonical":"Democratic Republic of the Congo","prior":2,"aliases":["DR Congo","DRC","Democratic Republic of Congo"]},{"canonical":"Saudi Arabia","prior":2,"aliases":[]},{"canonical":"Mexico","prior":2,"aliases":[]},{"canonical":"Indonesia","prior":2,"aliases":[]},{"canonical":"Sudan","prior":1,"aliases":[]},{"canonical":"Libya","prior":2,"aliases":[]},{"canonical":"Iran","prior":2,"aliases":[]},{"canonical":"Mongolia","prior":2,"aliases":[]},{"canonical":"Peru","prior":1,"aliases":[]},{"canonical":"Chad","prior":1,"aliases":[]},{"canonical":"Niger","prior":1,"aliases":[]},{"canonical":"Angola","prior":1,"aliases":[]},{"canonical":"Mali","prior":1,"aliases":[]},{"canonical":"South Africa","prior":1,"aliases":[]},{"canonical":"Colombia","prior":1,"aliases":[]},{"canonical":"Ethiopia","prior":1,"aliases":[]},{"canonical":"Bolivia","prior":1,"aliases":[]},{"canonical":"Mauritania","prior":1,"aliases":[]},{"canonical":"Egypt","prior":1,"aliases":[]}]', 'countries');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-nat-whale', 'Name a species of whale.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'The blue whale is the largest animal known to have lived, up to about 30 metres. Orcas and pilot whales are technically large dolphins, but both are called whales and are accepted.', 'https://en.wikipedia.org/wiki/List_of_cetaceans', 'Wikipedia: List of cetaceans', '2026-11-21', 'CC BY-SA 4.0', 'nature', 1, 0, '[{"canonical":"Blue whale","prior":30,"aliases":[]},{"canonical":"Humpback whale","prior":18,"aliases":["Humpback"]},{"canonical":"Orca","prior":12,"aliases":["Killer whale"]},{"canonical":"Sperm whale","prior":10,"aliases":[]},{"canonical":"Beluga","prior":6,"aliases":["Beluga whale","White whale"]},{"canonical":"Narwhal","prior":5,"aliases":[]},{"canonical":"Grey whale","prior":3,"aliases":["Gray whale"]},{"canonical":"Minke whale","prior":3,"aliases":["Minke"]},{"canonical":"Fin whale","prior":3,"aliases":["Finback"]},{"canonical":"Bowhead whale","prior":2,"aliases":["Bowhead"]},{"canonical":"Right whale","prior":2,"aliases":["North Atlantic right whale","Southern right whale"]},{"canonical":"Sei whale","prior":1,"aliases":[]},{"canonical":"Pilot whale","prior":1,"aliases":[]},{"canonical":"Bryde''s whale","prior":0.5,"aliases":["Brydes whale"]},{"canonical":"Pygmy sperm whale","prior":0.3,"aliases":[]},{"canonical":"Cuvier''s beaked whale","prior":0.3,"aliases":["Cuviers beaked whale"]},{"canonical":"Dwarf sperm whale","prior":0.2,"aliases":[]},{"canonical":"Pygmy right whale","prior":0.2,"aliases":[]},{"canonical":"False killer whale","prior":0.2,"aliases":[]},{"canonical":"Omura''s whale","prior":0.1,"aliases":["Omuras whale"]},{"canonical":"Baird''s beaked whale","prior":0.1,"aliases":["Bairds beaked whale"]},{"canonical":"Melon-headed whale","prior":0.1,"aliases":[]},{"canonical":"Northern bottlenose whale","prior":0.1,"aliases":[]}]', NULL);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-nat-heavy', 'Name a country in Oceania.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'This sample accepts the sovereign states usually counted in Oceania, including Australia and New Zealand. Pending verification.', 'https://en.wikipedia.org/wiki/Oceania', 'Wikipedia: Oceania', '2026-11-21', 'CC BY-SA 4.0', 'geography', 2, 0, '[{"canonical":"Australia","prior":16,"aliases":[]},{"canonical":"Fiji","prior":1,"aliases":[]},{"canonical":"Kiribati","prior":1,"aliases":[]},{"canonical":"Marshall Islands","prior":1,"aliases":[]},{"canonical":"Micronesia","prior":1,"aliases":[]},{"canonical":"Nauru","prior":1,"aliases":[]},{"canonical":"New Zealand","prior":8,"aliases":[]},{"canonical":"Palau","prior":1,"aliases":[]},{"canonical":"Papua New Guinea","prior":1,"aliases":[]},{"canonical":"Samoa","prior":1,"aliases":[]},{"canonical":"Solomon Islands","prior":1,"aliases":[]},{"canonical":"Tonga","prior":1,"aliases":[]},{"canonical":"Tuvalu","prior":1,"aliases":[]},{"canonical":"Vanuatu","prior":1,"aliases":[]}]', 'countries');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-nat-masses', 'Name a species of wild cat.', 'name_one', NULL, 'lower', NULL, '[]', '[]', 'There are about 40 wild cat species. The rusty-spotted cat is the smallest, around 1.5 kg. The tiger is the largest.', 'https://www.catsg.org/', 'IUCN Cat Specialist Group', '2026-11-21', 'IUCN SSC Cat Specialist Group public information', 'nature', 2, 0, '[{"canonical":"Lion","prior":30,"aliases":[]},{"canonical":"Tiger","prior":25,"aliases":[]},{"canonical":"Leopard","prior":12,"aliases":[]},{"canonical":"Jaguar","prior":10,"aliases":[]},{"canonical":"Cheetah","prior":10,"aliases":[]},{"canonical":"Snow leopard","prior":5,"aliases":[]},{"canonical":"Cougar","prior":4,"aliases":["Puma","Mountain lion"]},{"canonical":"Lynx","prior":1.5,"aliases":["Eurasian lynx","Canada lynx"]},{"canonical":"Clouded leopard","prior":1.5,"aliases":[]},{"canonical":"Bobcat","prior":0.5,"aliases":[]},{"canonical":"Ocelot","prior":0.5,"aliases":[]},{"canonical":"Serval","prior":0.5,"aliases":[]},{"canonical":"Caracal","prior":0.5,"aliases":[]},{"canonical":"Iberian lynx","prior":0.3,"aliases":[]},{"canonical":"Margay","prior":0.2,"aliases":[]},{"canonical":"Sand cat","prior":0.2,"aliases":[]},{"canonical":"Pallas''s cat","prior":0.2,"aliases":["Manul","Pallas cat"]},{"canonical":"Fishing cat","prior":0.2,"aliases":[]},{"canonical":"Black-footed cat","prior":0.2,"aliases":[]},{"canonical":"Jaguarundi","prior":0.2,"aliases":[]},{"canonical":"Rusty-spotted cat","prior":0.2,"aliases":[]},{"canonical":"Wildcat","prior":0.2,"aliases":["European wildcat","African wildcat"]},{"canonical":"Leopard cat","prior":0.1,"aliases":[]},{"canonical":"Jungle cat","prior":0.1,"aliases":[]},{"canonical":"Andean mountain cat","prior":0.1,"aliases":[]},{"canonical":"Kodkod","prior":0.1,"aliases":[]},{"canonical":"Oncilla","prior":0.1,"aliases":[]},{"canonical":"African golden cat","prior":0.1,"aliases":[]},{"canonical":"Asian golden cat","prior":0.1,"aliases":[]},{"canonical":"Flat-headed cat","prior":0.1,"aliases":[]},{"canonical":"Marbled cat","prior":0.1,"aliases":[]},{"canonical":"Geoffroy''s cat","prior":0.1,"aliases":["Geoffroys cat"]},{"canonical":"Bay cat","prior":0.05,"aliases":["Bornean bay cat"]}]', NULL);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-nat-wings', 'Name a bird that cannot fly.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'About 60 living bird species are flightless. The kākāpō of New Zealand is the only flightless parrot, and the heaviest parrot in the world.', 'https://en.wikipedia.org/wiki/Flightless_bird', 'Wikipedia: Flightless bird', '2026-11-21', 'CC BY-SA 4.0', 'nature', 1, 0, '[{"canonical":"Penguin","prior":30,"aliases":["Penguins","Emperor penguin","King penguin","Adelie penguin","Gentoo penguin"]},{"canonical":"Ostrich","prior":25,"aliases":[]},{"canonical":"Emu","prior":15,"aliases":[]},{"canonical":"Kiwi","prior":12,"aliases":[]},{"canonical":"Dodo","prior":6,"aliases":[]},{"canonical":"Cassowary","prior":6,"aliases":[]},{"canonical":"Rhea","prior":2,"aliases":[]},{"canonical":"Kākāpō","prior":2,"aliases":["Kakapo"]},{"canonical":"Moa","prior":0.5,"aliases":[]},{"canonical":"Takahē","prior":0.5,"aliases":["Takahe"]},{"canonical":"Weka","prior":0.3,"aliases":[]},{"canonical":"Flightless cormorant","prior":0.3,"aliases":["Galapagos cormorant"]},{"canonical":"Great auk","prior":0.3,"aliases":[]},{"canonical":"Elephant bird","prior":0.3,"aliases":[]},{"canonical":"Steamer duck","prior":0.2,"aliases":[]},{"canonical":"Inaccessible Island rail","prior":0.1,"aliases":[]}]', NULL);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-nat-gestation', 'Name a member of the European Union.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'The European Union has 27 member states. The United Kingdom left in 2020, so it does not count. The list is the public membership roll and is still marked unverified in this sample.', 'https://european-union.europa.eu/principles-countries-history/country-profiles_en', 'European Union', '2026-11-21', 'European Union public information', 'geography', 1, 0, '[{"canonical":"Austria","prior":2,"aliases":[]},{"canonical":"Belgium","prior":3,"aliases":[]},{"canonical":"Bulgaria","prior":1,"aliases":[]},{"canonical":"Croatia","prior":1,"aliases":[]},{"canonical":"Cyprus","prior":1,"aliases":[]},{"canonical":"Czechia","prior":2,"aliases":["Czech Republic"]},{"canonical":"Denmark","prior":3,"aliases":[]},{"canonical":"Estonia","prior":1,"aliases":[]},{"canonical":"Finland","prior":2,"aliases":[]},{"canonical":"France","prior":14,"aliases":[]},{"canonical":"Germany","prior":14,"aliases":[]},{"canonical":"Greece","prior":4,"aliases":[]},{"canonical":"Hungary","prior":2,"aliases":[]},{"canonical":"Ireland","prior":3,"aliases":[]},{"canonical":"Italy","prior":8,"aliases":[]},{"canonical":"Latvia","prior":1,"aliases":[]},{"canonical":"Lithuania","prior":1,"aliases":[]},{"canonical":"Luxembourg","prior":2,"aliases":[]},{"canonical":"Malta","prior":1,"aliases":[]},{"canonical":"Netherlands","prior":4,"aliases":[]},{"canonical":"Poland","prior":4,"aliases":[]},{"canonical":"Portugal","prior":3,"aliases":[]},{"canonical":"Romania","prior":2,"aliases":[]},{"canonical":"Slovakia","prior":1,"aliases":[]},{"canonical":"Slovenia","prior":1,"aliases":[]},{"canonical":"Spain","prior":8,"aliases":[]},{"canonical":"Sweden","prior":3,"aliases":[]}]', 'countries');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-geo-un', 'Name a landlocked country.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'There are 44 landlocked UN member and observer states, counting the Vatican. Liechtenstein and Uzbekistan are doubly landlocked: every neighbour is landlocked too.', 'https://en.wikipedia.org/wiki/Landlocked_country', 'Wikipedia: Landlocked country', '2026-11-21', 'CC BY-SA 4.0', 'geography', 2, 0, '[{"canonical":"Switzerland","prior":12,"aliases":[]},{"canonical":"Bolivia","prior":6,"aliases":[]},{"canonical":"Nepal","prior":6,"aliases":[]},{"canonical":"Austria","prior":4,"aliases":[]},{"canonical":"Mongolia","prior":4,"aliases":[]},{"canonical":"Paraguay","prior":4,"aliases":[]},{"canonical":"Afghanistan","prior":3,"aliases":[]},{"canonical":"Bhutan","prior":3,"aliases":[]},{"canonical":"Kazakhstan","prior":3,"aliases":[]},{"canonical":"Czechia","prior":2,"aliases":["Czech Republic"]},{"canonical":"Ethiopia","prior":2,"aliases":[]},{"canonical":"Hungary","prior":2,"aliases":[]},{"canonical":"Luxembourg","prior":2,"aliases":[]},{"canonical":"Vatican City","prior":2,"aliases":["Vatican","Holy See"]},{"canonical":"Laos","prior":1.5,"aliases":[]},{"canonical":"Andorra","prior":1,"aliases":[]},{"canonical":"Armenia","prior":1,"aliases":[]},{"canonical":"Azerbaijan","prior":1,"aliases":[]},{"canonical":"Belarus","prior":1,"aliases":[]},{"canonical":"Botswana","prior":1,"aliases":[]},{"canonical":"Burkina Faso","prior":1,"aliases":[]},{"canonical":"Chad","prior":1,"aliases":[]},{"canonical":"Kyrgyzstan","prior":1,"aliases":[]},{"canonical":"Lesotho","prior":1,"aliases":[]},{"canonical":"Liechtenstein","prior":1,"aliases":[]},{"canonical":"Mali","prior":1,"aliases":[]},{"canonical":"Moldova","prior":1,"aliases":[]},{"canonical":"Niger","prior":1,"aliases":[]},{"canonical":"Rwanda","prior":1,"aliases":[]},{"canonical":"San Marino","prior":1,"aliases":[]},{"canonical":"Serbia","prior":1,"aliases":[]},{"canonical":"Slovakia","prior":1,"aliases":[]},{"canonical":"Uganda","prior":1,"aliases":[]},{"canonical":"Uzbekistan","prior":1,"aliases":[]},{"canonical":"Zambia","prior":1,"aliases":[]},{"canonical":"Zimbabwe","prior":1,"aliases":[]},{"canonical":"Burundi","prior":0.5,"aliases":[]},{"canonical":"Central African Republic","prior":0.5,"aliases":[]},{"canonical":"Malawi","prior":0.5,"aliases":[]},{"canonical":"North Macedonia","prior":0.5,"aliases":["Macedonia"]},{"canonical":"South Sudan","prior":0.5,"aliases":[]},{"canonical":"Tajikistan","prior":0.5,"aliases":[]},{"canonical":"Turkmenistan","prior":0.5,"aliases":[]},{"canonical":"Eswatini","prior":0.3,"aliases":["Swaziland"]}]', 'countries');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-geo-canada', 'Name a permanent member of the United Nations Security Council.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'The five permanent members are China, France, Russia, the United Kingdom, and the United States. Pending verification.', 'https://www.un.org/securitycouncil/content/current-members', 'United Nations Security Council', '2026-11-21', 'United Nations public information', 'geography', 1, 0, '[{"canonical":"China","prior":6,"aliases":["PRC"]},{"canonical":"France","prior":6,"aliases":[]},{"canonical":"Russia","prior":6,"aliases":["Russian Federation"]},{"canonical":"United Kingdom","prior":6,"aliases":["UK","Britain"]},{"canonical":"United States","prior":6,"aliases":["USA","US","America"]}]', 'countries');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-geo-areas', 'Name a country that borders China.', 'name_one', NULL, 'lower', NULL, '[]', '[]', 'China borders 14 countries, tied with Russia for the most of any country. Its shortest land border is with Afghanistan, about 76 km.', 'https://www.cia.gov/the-world-factbook/countries/china/', 'CIA World Factbook: China', '2026-11-21', 'CIA World Factbook public domain', 'geography', 2, 0, '[{"canonical":"India","prior":20,"aliases":[]},{"canonical":"Russia","prior":15,"aliases":["Russian Federation"]},{"canonical":"Mongolia","prior":8,"aliases":[]},{"canonical":"Pakistan","prior":8,"aliases":[]},{"canonical":"Nepal","prior":8,"aliases":[]},{"canonical":"North Korea","prior":6,"aliases":["DPRK"]},{"canonical":"Vietnam","prior":6,"aliases":["Viet Nam"]},{"canonical":"Myanmar","prior":4,"aliases":["Burma"]},{"canonical":"Bhutan","prior":3,"aliases":[]},{"canonical":"Kazakhstan","prior":3,"aliases":[]},{"canonical":"Afghanistan","prior":2,"aliases":[]},{"canonical":"Laos","prior":2,"aliases":[]},{"canonical":"Kyrgyzstan","prior":1,"aliases":[]},{"canonical":"Tajikistan","prior":1,"aliases":[]}]', 'countries');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-geo-russia', 'Name a country whose English name starts with S.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Twenty-six UN member states start with S, more than any other letter. Scotland is a country within the United Kingdom, not a UN member, so it is not on the list.', 'https://www.un.org/en/about-us/member-states', 'United Nations member states', '2026-11-21', 'United Nations public information', 'geography', 1, 0, '[{"canonical":"Spain","prior":20,"aliases":[]},{"canonical":"Sweden","prior":12,"aliases":[]},{"canonical":"Switzerland","prior":10,"aliases":[]},{"canonical":"Saudi Arabia","prior":8,"aliases":[]},{"canonical":"South Africa","prior":8,"aliases":[]},{"canonical":"Singapore","prior":6,"aliases":[]},{"canonical":"South Korea","prior":4,"aliases":["Korea, Republic of"]},{"canonical":"Sri Lanka","prior":4,"aliases":[]},{"canonical":"Syria","prior":3,"aliases":[]},{"canonical":"Somalia","prior":2,"aliases":[]},{"canonical":"Sudan","prior":2,"aliases":[]},{"canonical":"Senegal","prior":2,"aliases":[]},{"canonical":"Serbia","prior":2,"aliases":[]},{"canonical":"Slovakia","prior":1,"aliases":[]},{"canonical":"Slovenia","prior":1,"aliases":[]},{"canonical":"South Sudan","prior":1,"aliases":[]},{"canonical":"Suriname","prior":1,"aliases":[]},{"canonical":"Sierra Leone","prior":1,"aliases":[]},{"canonical":"Samoa","prior":0.5,"aliases":[]},{"canonical":"San Marino","prior":0.5,"aliases":[]},{"canonical":"Seychelles","prior":0.5,"aliases":[]},{"canonical":"Solomon Islands","prior":0.3,"aliases":[]},{"canonical":"Saint Lucia","prior":0.3,"aliases":["St Lucia","St. Lucia"]},{"canonical":"Sao Tome and Principe","prior":0.2,"aliases":["São Tomé and Príncipe"]},{"canonical":"Saint Kitts and Nevis","prior":0.2,"aliases":["St Kitts and Nevis"]},{"canonical":"Saint Vincent and the Grenadines","prior":0.2,"aliases":["St Vincent and the Grenadines"]}]', 'countries');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-geo-brazil', 'Name a country in South America.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Twelve sovereign countries sit on the South American continent. French Guiana is not a country, so it is not accepted. Pending verification.', 'https://en.wikipedia.org/wiki/South_America', 'Wikipedia: South America', '2026-11-21', 'CC BY-SA 4.0', 'geography', 1, 0, '[{"canonical":"Argentina","prior":6,"aliases":[]},{"canonical":"Bolivia","prior":2,"aliases":[]},{"canonical":"Brazil","prior":16,"aliases":[]},{"canonical":"Chile","prior":2,"aliases":[]},{"canonical":"Colombia","prior":2,"aliases":[]},{"canonical":"Ecuador","prior":2,"aliases":[]},{"canonical":"Guyana","prior":2,"aliases":[]},{"canonical":"Paraguay","prior":2,"aliases":[]},{"canonical":"Peru","prior":2,"aliases":[]},{"canonical":"Suriname","prior":2,"aliases":[]},{"canonical":"Uruguay","prior":2,"aliases":[]},{"canonical":"Venezuela","prior":2,"aliases":[]}]', 'countries');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-sci-c14', 'Name a chemical element that is a gas at room temperature.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Eleven elements are gases at 25 °C and normal pressure: the six noble gases plus hydrogen, nitrogen, oxygen, fluorine and chlorine. Oganesson is too short-lived to say.', 'https://www.rsc.org/periodic-table', 'Royal Society of Chemistry periodic table', '2026-11-21', 'Royal Society of Chemistry periodic table', 'science', 1, 0, '[{"canonical":"Oxygen","prior":18,"aliases":[]},{"canonical":"Hydrogen","prior":15,"aliases":[]},{"canonical":"Helium","prior":14,"aliases":[]},{"canonical":"Nitrogen","prior":10,"aliases":[]},{"canonical":"Chlorine","prior":5,"aliases":[]},{"canonical":"Neon","prior":4,"aliases":[]},{"canonical":"Argon","prior":3,"aliases":[]},{"canonical":"Fluorine","prior":2,"aliases":[]},{"canonical":"Krypton","prior":2,"aliases":[]},{"canonical":"Xenon","prior":1.5,"aliases":[]},{"canonical":"Radon","prior":1,"aliases":[]}]', 'elements');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-sci-melt', 'Name an alkaline earth metal.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Group 2 is beryllium, magnesium, calcium, strontium, barium, and radium. Pending verification.', 'https://www.rsc.org/periodic-table', 'Royal Society of Chemistry periodic table', '2026-11-21', 'Royal Society of Chemistry periodic table', 'science', 2, 0, '[{"canonical":"Beryllium","prior":2,"aliases":[]},{"canonical":"Magnesium","prior":8,"aliases":[]},{"canonical":"Calcium","prior":8,"aliases":[]},{"canonical":"Strontium","prior":2,"aliases":[]},{"canonical":"Barium","prior":2,"aliases":[]},{"canonical":"Radium","prior":2,"aliases":[]}]', 'elements');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-sci-metals', 'Name a metal element used in coins.', 'name_one', NULL, 'lower', NULL, '[]', '[]', 'Most modern coins are alloys. The US nickel is 75% copper, and the euro''s gold-coloured coins are Nordic gold: copper, aluminium, zinc and tin.', 'https://en.wikipedia.org/wiki/Coin_metal', 'Wikipedia: Coin metal', '2026-11-21', 'CC BY-SA 4.0', 'science', 2, 0, '[{"canonical":"Copper","prior":20,"aliases":[]},{"canonical":"Gold","prior":15,"aliases":[]},{"canonical":"Silver","prior":15,"aliases":[]},{"canonical":"Nickel","prior":14,"aliases":[]},{"canonical":"Zinc","prior":8,"aliases":[]},{"canonical":"Aluminum","prior":4,"aliases":["Aluminium"]},{"canonical":"Iron","prior":2,"aliases":[]},{"canonical":"Tin","prior":2,"aliases":[]},{"canonical":"Manganese","prior":1,"aliases":[]},{"canonical":"Platinum","prior":1,"aliases":[]},{"canonical":"Palladium","prior":0.5,"aliases":[]},{"canonical":"Chromium","prior":0.3,"aliases":[]}]', 'elements');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-sci-sound', 'Name a chemical element named after a place.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Four elements are named after one Swedish village, Ytterby: yttrium, ytterbium, terbium and erbium. Copper comes from the Latin for Cyprus.', 'https://en.wikipedia.org/wiki/List_of_chemical_element_name_etymologies', 'Wikipedia: List of chemical element name etymologies', '2026-11-21', 'CC BY-SA 4.0', 'science', 3, 0, '[{"canonical":"Francium","prior":8,"aliases":[]},{"canonical":"Polonium","prior":8,"aliases":[]},{"canonical":"Americium","prior":6,"aliases":[]},{"canonical":"Californium","prior":5,"aliases":[]},{"canonical":"Germanium","prior":4,"aliases":[]},{"canonical":"Europium","prior":3,"aliases":[]},{"canonical":"Gallium","prior":3,"aliases":[]},{"canonical":"Berkelium","prior":2,"aliases":[]},{"canonical":"Scandium","prior":1,"aliases":[]},{"canonical":"Darmstadtium","prior":1,"aliases":[]},{"canonical":"Nihonium","prior":1,"aliases":[]},{"canonical":"Moscovium","prior":1,"aliases":[]},{"canonical":"Tennessine","prior":1,"aliases":[]},{"canonical":"Hassium","prior":0.5,"aliases":[]},{"canonical":"Dubnium","prior":0.5,"aliases":[]},{"canonical":"Ruthenium","prior":0.5,"aliases":[]},{"canonical":"Strontium","prior":0.5,"aliases":[]},{"canonical":"Yttrium","prior":0.5,"aliases":[]},{"canonical":"Ytterbium","prior":0.5,"aliases":[]},{"canonical":"Terbium","prior":0.5,"aliases":[]},{"canonical":"Erbium","prior":0.5,"aliases":[]},{"canonical":"Lutetium","prior":0.3,"aliases":[]},{"canonical":"Hafnium","prior":0.3,"aliases":[]},{"canonical":"Holmium","prior":0.3,"aliases":[]},{"canonical":"Rhenium","prior":0.3,"aliases":[]},{"canonical":"Magnesium","prior":0.3,"aliases":[]},{"canonical":"Copper","prior":0.2,"aliases":[]}]', 'elements');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-sci-atomic', 'Name a chemical element whose symbol is a single letter.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Fourteen elements use a one-letter symbol: H, B, C, N, O, F, P, S, K, V, Y, I, W, and U. Gold is Au and lead is Pb, so neither counts. Pending verification.', 'https://www.rsc.org/periodic-table', 'Royal Society of Chemistry periodic table', '2026-11-21', 'Royal Society of Chemistry periodic table', 'science', 2, 0, '[{"canonical":"Hydrogen","prior":10,"aliases":[]},{"canonical":"Boron","prior":3,"aliases":[]},{"canonical":"Carbon","prior":12,"aliases":[]},{"canonical":"Nitrogen","prior":6,"aliases":[]},{"canonical":"Oxygen","prior":12,"aliases":[]},{"canonical":"Fluorine","prior":3,"aliases":[]},{"canonical":"Phosphorus","prior":2,"aliases":[]},{"canonical":"Sulfur","prior":3,"aliases":["Sulphur"]},{"canonical":"Potassium","prior":3,"aliases":[]},{"canonical":"Vanadium","prior":1,"aliases":[]},{"canonical":"Yttrium","prior":1,"aliases":[]},{"canonical":"Iodine","prior":4,"aliases":[]},{"canonical":"Tungsten","prior":2,"aliases":["Wolfram"]},{"canonical":"Uranium","prior":8,"aliases":[]}]', 'elements');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-cul-marathon', 'Name a sport at the Paris 2024 Summer Olympics.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Paris 2024 held 329 events across 32 sports. Breaking made its Olympic debut there and is not on the programme for Los Angeles 2028.', 'https://olympics.com/en/paris-2024/sports', 'Olympics.com: Paris 2024', '2026-11-21', 'IOC public information', 'culture', 1, 0, '[{"canonical":"Athletics","prior":20,"aliases":["Track and field","Running"]},{"canonical":"Swimming","prior":20,"aliases":[]},{"canonical":"Gymnastics","prior":12,"aliases":[]},{"canonical":"Basketball","prior":8,"aliases":[]},{"canonical":"Football","prior":8,"aliases":["Soccer"]},{"canonical":"Tennis","prior":5,"aliases":[]},{"canonical":"Boxing","prior":5,"aliases":[]},{"canonical":"Cycling","prior":4,"aliases":[]},{"canonical":"Volleyball","prior":4,"aliases":[]},{"canonical":"Rowing","prior":3,"aliases":[]},{"canonical":"Diving","prior":3,"aliases":[]},{"canonical":"Fencing","prior":2,"aliases":[]},{"canonical":"Archery","prior":2,"aliases":[]},{"canonical":"Judo","prior":2,"aliases":[]},{"canonical":"Wrestling","prior":2,"aliases":[]},{"canonical":"Weightlifting","prior":2,"aliases":[]},{"canonical":"Table tennis","prior":2,"aliases":["Ping pong"]},{"canonical":"Badminton","prior":2,"aliases":[]},{"canonical":"Sailing","prior":1,"aliases":[]},{"canonical":"Equestrian","prior":1,"aliases":["Horse riding","Show jumping","Dressage"]},{"canonical":"Shooting","prior":1,"aliases":[]},{"canonical":"Taekwondo","prior":1,"aliases":[]},{"canonical":"Handball","prior":1,"aliases":[]},{"canonical":"Hockey","prior":1,"aliases":["Field hockey"]},{"canonical":"Golf","prior":1,"aliases":[]},{"canonical":"Rugby sevens","prior":1,"aliases":["Rugby"]},{"canonical":"Canoeing","prior":1,"aliases":["Canoe","Kayaking"]},{"canonical":"Triathlon","prior":1,"aliases":[]},{"canonical":"Water polo","prior":1,"aliases":[]},{"canonical":"Skateboarding","prior":1,"aliases":[]},{"canonical":"Surfing","prior":1,"aliases":[]},{"canonical":"Beach volleyball","prior":1,"aliases":[]},{"canonical":"Sport climbing","prior":0.5,"aliases":["Climbing"]},{"canonical":"Breaking","prior":0.5,"aliases":["Breakdancing","Breakdance"]},{"canonical":"Modern pentathlon","prior":0.3,"aliases":["Pentathlon"]},{"canonical":"Artistic swimming","prior":0.3,"aliases":["Synchronised swimming","Synchronized swimming"]},{"canonical":"Trampoline","prior":0.3,"aliases":[]},{"canonical":"BMX","prior":0.3,"aliases":[]}]', NULL);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-cul-premiere', 'Name a Nordic country.', 'name_one', NULL, 'lower', NULL, '[]', '[]', 'This sample treats the Nordic countries as Denmark, Finland, Iceland, Norway, and Sweden. Pending verification.', 'https://www.norden.org/en/information/facts-about-nordic-countries', 'Nordic Council', '2026-11-21', 'Nordic Council public information', 'geography', 1, 0, '[{"canonical":"Denmark","prior":4,"aliases":[]},{"canonical":"Finland","prior":4,"aliases":[]},{"canonical":"Iceland","prior":4,"aliases":[]},{"canonical":"Norway","prior":8,"aliases":[]},{"canonical":"Sweden","prior":8,"aliases":[]}]', 'countries');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-cul-works', 'Name a painting by Vincent van Gogh.', 'name_one', NULL, 'lower', NULL, '[]', '[]', 'Van Gogh made about 900 paintings in roughly a decade, most of them in his last two years. He sold very few while he was alive.', 'https://www.vangoghmuseum.nl/en/collection', 'Van Gogh Museum', '2026-11-21', 'Van Gogh Museum public collection', 'culture', 2, 0, '[{"canonical":"The Starry Night","prior":40,"aliases":["Starry Night"]},{"canonical":"Sunflowers","prior":20,"aliases":["The Sunflowers"]},{"canonical":"Self-Portrait with Bandaged Ear","prior":6,"aliases":["Self Portrait","Self-Portrait"]},{"canonical":"Café Terrace at Night","prior":4,"aliases":["Cafe Terrace at Night","Terrace of a Café at Night"]},{"canonical":"Bedroom in Arles","prior":4,"aliases":["The Bedroom"]},{"canonical":"The Potato Eaters","prior":3,"aliases":["Potato Eaters"]},{"canonical":"Irises","prior":3,"aliases":[]},{"canonical":"Wheatfield with Crows","prior":3,"aliases":["Wheat Field with Crows"]},{"canonical":"Almond Blossoms","prior":3,"aliases":["Almond Blossom"]},{"canonical":"Starry Night Over the Rhône","prior":2,"aliases":["Starry Night Over the Rhone"]},{"canonical":"The Night Café","prior":1.5,"aliases":["Night Cafe","The Night Cafe"]},{"canonical":"The Yellow House","prior":1,"aliases":[]},{"canonical":"Portrait of Dr. Gachet","prior":1,"aliases":["Dr Gachet","Portrait of Dr Gachet"]},{"canonical":"Wheat Field with Cypresses","prior":0.5,"aliases":[]},{"canonical":"The Red Vineyard","prior":0.5,"aliases":[]},{"canonical":"The Church at Auvers","prior":0.5,"aliases":[]},{"canonical":"Olive Trees","prior":0.5,"aliases":[]},{"canonical":"Cypresses","prior":0.3,"aliases":[]},{"canonical":"The Sower","prior":0.3,"aliases":[]},{"canonical":"Skull of a Skeleton with Burning Cigarette","prior":0.3,"aliases":[]},{"canonical":"Portrait of Joseph Roulin","prior":0.2,"aliases":[]},{"canonical":"L''Arlésienne","prior":0.2,"aliases":["LArlesienne","The Arlesienne"]},{"canonical":"The Mulberry Tree","prior":0.2,"aliases":[]},{"canonical":"Langlois Bridge","prior":0.2,"aliases":["The Langlois Bridge at Arles"]},{"canonical":"Peach Tree in Blossom","prior":0.1,"aliases":[]}]', NULL);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-cul-paintings', 'Name an Asian country with more than 50 million people.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'UN 2024 estimates. Russia is left off this sample list so the question stays about Asia. Egypt is counted with Africa. Pending verification.', 'https://population.un.org/wpp/', 'UN World Population Prospects 2024', '2026-11-21', 'United Nations public information', 'geography', 2, 0, '[{"canonical":"India","prior":24,"aliases":["Bharat"]},{"canonical":"China","prior":22,"aliases":["PRC","People''s Republic of China"]},{"canonical":"Indonesia","prior":6,"aliases":[]},{"canonical":"Pakistan","prior":4,"aliases":[]},{"canonical":"Bangladesh","prior":3,"aliases":[]},{"canonical":"Japan","prior":8,"aliases":[]},{"canonical":"Philippines","prior":2,"aliases":[]},{"canonical":"Vietnam","prior":2,"aliases":["Viet Nam"]},{"canonical":"Iran","prior":2,"aliases":[]},{"canonical":"Turkey","prior":3,"aliases":["Turkiye","Türkiye"]},{"canonical":"Thailand","prior":2,"aliases":[]},{"canonical":"Myanmar","prior":1,"aliases":["Burma"]},{"canonical":"South Korea","prior":3,"aliases":["Republic of Korea"]}]', 'countries');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-cul-shakespeare', 'Name a play by William Shakespeare.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'The First Folio of 1623 collected 36 plays. Modern editions usually add Pericles and The Two Noble Kinsmen, which Shakespeare co-wrote.', 'https://www.folger.edu/explore/shakespeares-works/', 'Folger Shakespeare Library', '2026-11-21', 'Folger Shakespeare Library public information', 'culture', 1, 0, '[{"canonical":"Romeo and Juliet","prior":30,"aliases":["Romeo & Juliet"]},{"canonical":"Hamlet","prior":25,"aliases":[]},{"canonical":"Macbeth","prior":15,"aliases":[]},{"canonical":"Othello","prior":6,"aliases":[]},{"canonical":"A Midsummer Night''s Dream","prior":6,"aliases":["Midsummer Nights Dream","A Midsummer Nights Dream"]},{"canonical":"King Lear","prior":5,"aliases":[]},{"canonical":"Julius Caesar","prior":4,"aliases":[]},{"canonical":"The Tempest","prior":3,"aliases":["Tempest"]},{"canonical":"The Merchant of Venice","prior":3,"aliases":["Merchant of Venice"]},{"canonical":"Twelfth Night","prior":2,"aliases":[]},{"canonical":"Much Ado About Nothing","prior":2,"aliases":[]},{"canonical":"As You Like It","prior":1.5,"aliases":[]},{"canonical":"The Taming of the Shrew","prior":1.5,"aliases":["Taming of the Shrew"]},{"canonical":"Richard III","prior":1,"aliases":["Richard the Third"]},{"canonical":"Henry V","prior":1,"aliases":["Henry the Fifth"]},{"canonical":"Antony and Cleopatra","prior":1,"aliases":[]},{"canonical":"The Winter''s Tale","prior":0.5,"aliases":["Winters Tale"]},{"canonical":"The Comedy of Errors","prior":0.4,"aliases":["Comedy of Errors"]},{"canonical":"Coriolanus","prior":0.3,"aliases":[]},{"canonical":"Titus Andronicus","prior":0.3,"aliases":[]},{"canonical":"Measure for Measure","prior":0.3,"aliases":[]},{"canonical":"All''s Well That Ends Well","prior":0.3,"aliases":["Alls Well That Ends Well"]},{"canonical":"Richard II","prior":0.3,"aliases":[]},{"canonical":"Henry IV, Part 1","prior":0.3,"aliases":["Henry IV","Henry IV Part 1"]},{"canonical":"Love''s Labour''s Lost","prior":0.2,"aliases":["Loves Labours Lost"]},{"canonical":"The Two Gentlemen of Verona","prior":0.2,"aliases":["Two Gentlemen of Verona"]},{"canonical":"The Merry Wives of Windsor","prior":0.2,"aliases":["Merry Wives of Windsor"]},{"canonical":"Henry IV, Part 2","prior":0.1,"aliases":["Henry IV Part 2"]},{"canonical":"Henry VI, Part 1","prior":0.1,"aliases":["Henry VI","Henry VI Part 1"]},{"canonical":"Henry VI, Part 2","prior":0.05,"aliases":["Henry VI Part 2"]},{"canonical":"Henry VI, Part 3","prior":0.05,"aliases":["Henry VI Part 3"]},{"canonical":"Henry VIII","prior":0.1,"aliases":[]},{"canonical":"King John","prior":0.1,"aliases":[]},{"canonical":"Troilus and Cressida","prior":0.1,"aliases":[]},{"canonical":"Timon of Athens","prior":0.1,"aliases":[]},{"canonical":"Pericles, Prince of Tyre","prior":0.1,"aliases":["Pericles"]},{"canonical":"Cymbeline","prior":0.1,"aliases":[]},{"canonical":"The Two Noble Kinsmen","prior":0.05,"aliases":["Two Noble Kinsmen"]}]', NULL);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-long-equator', 'Name a country the equator passes through.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'The equator crosses 13 countries'' land or waters. Ecuador is named after it. In the Maldives it passes only through water between the atolls, so it is not counted here.', 'https://en.wikipedia.org/wiki/Equator', 'Wikipedia: Equator', '2026-11-21', 'CC BY-SA 4.0', 'geography', 2, 0, '[{"canonical":"Ecuador","prior":25,"aliases":[]},{"canonical":"Brazil","prior":20,"aliases":[]},{"canonical":"Kenya","prior":10,"aliases":[]},{"canonical":"Indonesia","prior":10,"aliases":[]},{"canonical":"Colombia","prior":8,"aliases":[]},{"canonical":"Uganda","prior":5,"aliases":[]},{"canonical":"Democratic Republic of the Congo","prior":4,"aliases":["DR Congo","DRC","Congo-Kinshasa"]},{"canonical":"Gabon","prior":2,"aliases":[]},{"canonical":"Republic of the Congo","prior":2,"aliases":["Congo-Brazzaville","Congo"]},{"canonical":"Somalia","prior":2,"aliases":[]},{"canonical":"Kiribati","prior":1,"aliases":[]},{"canonical":"Sao Tome and Principe","prior":1,"aliases":["São Tomé and Príncipe"]}]', 'countries');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-long-span', 'Name a sovereign country in the Caribbean.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Sovereign Caribbean states only. Territories such as Puerto Rico are not countries on this list. Pending verification.', 'https://en.wikipedia.org/wiki/Caribbean', 'Wikipedia: Caribbean', '2026-11-21', 'CC BY-SA 4.0', 'geography', 2, 0, '[{"canonical":"Antigua and Barbuda","prior":2,"aliases":[]},{"canonical":"Bahamas","prior":2,"aliases":["The Bahamas"]},{"canonical":"Barbados","prior":2,"aliases":[]},{"canonical":"Cuba","prior":8,"aliases":[]},{"canonical":"Dominica","prior":2,"aliases":[]},{"canonical":"Dominican Republic","prior":2,"aliases":[]},{"canonical":"Grenada","prior":2,"aliases":[]},{"canonical":"Haiti","prior":2,"aliases":[]},{"canonical":"Jamaica","prior":8,"aliases":[]},{"canonical":"Saint Kitts and Nevis","prior":2,"aliases":[]},{"canonical":"Saint Lucia","prior":2,"aliases":[]},{"canonical":"Saint Vincent and the Grenadines","prior":2,"aliases":[]},{"canonical":"Trinidad and Tobago","prior":2,"aliases":[]}]', 'countries');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-long-rocky', 'Name a desert.', 'name_one', NULL, 'lower', NULL, '[]', '[]', 'A desert is defined by how little rain falls, not by heat. By that measure the largest desert on Earth is Antarctica, and the Sahara is the largest hot one.', 'https://en.wikipedia.org/wiki/List_of_deserts_by_area', 'Wikipedia: List of deserts by area', '2026-11-21', 'CC BY-SA 4.0', 'geography', 1, 0, '[{"canonical":"Sahara","prior":35,"aliases":["Sahara Desert"]},{"canonical":"Gobi","prior":12,"aliases":["Gobi Desert"]},{"canonical":"Kalahari","prior":8,"aliases":[]},{"canonical":"Atacama","prior":8,"aliases":[]},{"canonical":"Mojave","prior":5,"aliases":["Mohave"]},{"canonical":"Arabian Desert","prior":4,"aliases":["Arabian"]},{"canonical":"Antarctic Desert","prior":3,"aliases":["Antarctica","Antarctic"]},{"canonical":"Sonoran","prior":3,"aliases":[]},{"canonical":"Thar","prior":3,"aliases":["Great Indian Desert"]},{"canonical":"Namib","prior":3,"aliases":[]},{"canonical":"Taklamakan","prior":1.5,"aliases":["Taklimakan"]},{"canonical":"Great Victoria Desert","prior":1,"aliases":["Great Victoria"]},{"canonical":"Chihuahuan","prior":1,"aliases":[]},{"canonical":"Patagonian Desert","prior":1,"aliases":["Patagonian"]},{"canonical":"Arctic Desert","prior":1,"aliases":["Arctic"]},{"canonical":"Gibson Desert","prior":0.5,"aliases":["Gibson"]},{"canonical":"Simpson Desert","prior":0.5,"aliases":["Simpson"]},{"canonical":"Great Basin Desert","prior":0.5,"aliases":["Great Basin"]},{"canonical":"Karakum","prior":0.5,"aliases":["Kara Kum"]},{"canonical":"Syrian Desert","prior":0.5,"aliases":[]},{"canonical":"Rub'' al Khali","prior":0.5,"aliases":["Empty Quarter","Rub al Khali"]},{"canonical":"Great Sandy Desert","prior":0.5,"aliases":["Great Sandy"]},{"canonical":"Negev","prior":0.5,"aliases":[]},{"canonical":"Kyzylkum","prior":0.3,"aliases":["Kyzyl Kum"]},{"canonical":"Danakil","prior":0.3,"aliases":[]},{"canonical":"Tanami","prior":0.3,"aliases":[]},{"canonical":"Dasht-e Kavir","prior":0.2,"aliases":[]},{"canonical":"Dasht-e Lut","prior":0.2,"aliases":["Lut Desert"]},{"canonical":"Painted Desert","prior":0.2,"aliases":[]}]', NULL);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-long-elements', 'Name a chemical element whose symbol comes from its Latin or German name.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Eleven elements have symbols that do not match their English names. Au is from the Latin aurum, Fe from ferrum, and W from the German Wolfram.', 'https://www.rsc.org/periodic-table', 'Royal Society of Chemistry periodic table', '2026-11-21', 'Royal Society of Chemistry periodic table', 'science', 2, 0, '[{"canonical":"Gold","prior":15,"aliases":[]},{"canonical":"Sodium","prior":15,"aliases":[]},{"canonical":"Iron","prior":14,"aliases":[]},{"canonical":"Potassium","prior":12,"aliases":[]},{"canonical":"Silver","prior":12,"aliases":[]},{"canonical":"Lead","prior":10,"aliases":[]},{"canonical":"Copper","prior":8,"aliases":[]},{"canonical":"Mercury","prior":8,"aliases":[]},{"canonical":"Tin","prior":4,"aliases":[]},{"canonical":"Tungsten","prior":4,"aliases":[]},{"canonical":"Antimony","prior":2,"aliases":[]}]', 'elements');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set) VALUES ('q-long-trenches', 'Name a chemical element with an atomic number greater than 92.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Uranium is 92. Everything past it, from neptunium to oganesson, was made in a lab or a reactor. The names follow the IUPAC table. Pending verification.', 'https://iupac.org/what-we-do/periodic-table-of-elements/', 'IUPAC', '2026-11-21', 'IUPAC', 'science', 2, 0, '[{"canonical":"Neptunium","prior":1,"aliases":[]},{"canonical":"Plutonium","prior":18,"aliases":[]},{"canonical":"Americium","prior":1,"aliases":[]},{"canonical":"Curium","prior":1,"aliases":[]},{"canonical":"Berkelium","prior":1,"aliases":[]},{"canonical":"Californium","prior":1,"aliases":[]},{"canonical":"Einsteinium","prior":1,"aliases":[]},{"canonical":"Fermium","prior":1,"aliases":[]},{"canonical":"Mendelevium","prior":1,"aliases":[]},{"canonical":"Nobelium","prior":1,"aliases":[]},{"canonical":"Lawrencium","prior":1,"aliases":[]},{"canonical":"Rutherfordium","prior":1,"aliases":[]},{"canonical":"Dubnium","prior":1,"aliases":[]},{"canonical":"Seaborgium","prior":1,"aliases":[]},{"canonical":"Bohrium","prior":1,"aliases":[]},{"canonical":"Hassium","prior":1,"aliases":[]},{"canonical":"Meitnerium","prior":1,"aliases":[]},{"canonical":"Darmstadtium","prior":1,"aliases":[]},{"canonical":"Roentgenium","prior":1,"aliases":[]},{"canonical":"Copernicium","prior":1,"aliases":[]},{"canonical":"Nihonium","prior":1,"aliases":[]},{"canonical":"Flerovium","prior":1,"aliases":[]},{"canonical":"Moscovium","prior":1,"aliases":[]},{"canonical":"Livermorium","prior":1,"aliases":[]},{"canonical":"Tennessine","prior":1,"aliases":[]},{"canonical":"Oganesson","prior":1,"aliases":[]}]', 'elements');
