INSERT INTO puzzles (slot, theme, blurb, question_ids) VALUES (5, 'Living world', 'Whales, wild cats, flightless birds, and two maps.', '["q-nat-whale","q-nat-heavy","q-nat-masses","q-nat-wings","q-nat-gestation"]');
