INSERT INTO puzzles (slot, theme, blurb, question_ids) VALUES (7, 'Laboratory', 'Gases, coin metals, and elements named after places.', '["q-sci-c14","q-sci-melt","q-sci-metals","q-sci-sound","q-sci-atomic"]');
